#pragma once
#include "servo_core.hpp"
#include "telemetry.hpp"
#include <atomic>
#include <string>
#include <utility>
namespace franka { class Robot; }
namespace m80 {
// These records are supplied by the site integration, not generated by a
// simulation export. They state required evidence; they do not certify it.
struct FieldContext {
  std::string calibration_record,commissioning_record;
  bool field_planned=false,tool_verified=false,io_verified=false,torque_budget_verified=false;
  double expected_tool_mass_kg=-1.,expected_load_mass_kg=-1.;
  double command_fraction=.1;
  double maximum_external_force_n=0.,maximum_external_torque_nm=0.;
  StageTelemetry* telemetry=nullptr;
};
struct AtomicGates {
  std::atomic<bool> io_ready{false};
  std::atomic<bool> abort_requested{false};
};
struct ServoReport {
  unsigned long samples=0;
  double maximum_period_s=0.,maximum_tracking_error_rad=0.,maximum_torque_rate_nm_s=0.;
  bool completed=false;
  std::uint64_t telemetry_dropped_samples=0;
};
void validate_field_context(const FieldContext&);
void validate_external_wrench(const std::array<double,6>&,const FieldContext&);

// Share every failure, including validation/readiness/state-read failures
// before control() begins. Never clear a previous stop automatically.
template <class Work>
auto with_shared_abort(AtomicGates& gates,Work&& work)
    -> decltype(std::forward<Work>(work)()) {
  try {
    return std::forward<Work>(work)();
  } catch(...) {
    gates.abort_requested.store(true);
    throw;
  }
}
// There is no executable that blindly replays a simulation file. A calibrated
// field application calls this stage API after measured task interlocks.
ServoReport run_joint_stage(franka::Robot&,const Trajectory&,const FieldContext&,AtomicGates&);
} // namespace m80
